#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Create a string stream to hold the markdown text
    std::stringstream markdownStream(markdown);

    // Create a string stream to hold the HTML text
    std::stringstream htmlStream;

    // Copy the markdown text to the HTML stream
    htmlStream << markdownStream;

    // Return the HTML text
    return htmlStream.str();
}

int main() {
    std::string markdown = "# Hello, World!\nThis is a markdown text.\n*bold* text\n_italic_ text\n- list";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

This function uses a `std::stringstream` to hold the markdown text and then copies it to another `std::stringstream` to hold the HTML text. The resulting HTML text is then returned.

Note that this function does not handle all markdown features, such as links, images, or tables. For a more robust implementation, you may want to use a markdown library, such as Pandoc or Markdown Extra.

